/** Native predicate fields for routes that diverge from their concrete carrier,
 * with runtime intersection semantics: a predicate must be valid for every
 * concrete type in the route's expansion. Concrete routes resolve through
 * NativeNodeFields with optionality stripped (their predicate fields and field
 * types coincide by schema validation). */
export interface NativeRoutePredicates {
  Function: {
    readonly async: boolean;
    readonly parameterCount: number;
    readonly bodyStart: number;
    readonly bodyEnd: number;
  };
  MemberExpression: {
    readonly write: boolean;
  };
  MetaProperty: {
    readonly meta: 'import' | 'new';
    readonly property: 'meta' | 'target';
  };
  ReferencedIdentifier: {
    readonly name: string;
    readonly global: boolean;
    readonly read: boolean;
    readonly write: boolean;
    readonly memberWrite: boolean;
    readonly bindingScopeId: number;
    readonly binding: boolean;
  };
  FunctionDeclaration: {
    readonly nodeKind: 'FunctionDeclaration';
    readonly async: boolean;
    readonly generator: boolean;
    readonly parameterCount: number;
    readonly name: string;
    readonly bodyStart: number;
    readonly bodyEnd: number;
  };
  FunctionExpression: {
    readonly nodeKind: 'FunctionExpression';
    readonly async: boolean;
    readonly generator: boolean;
    readonly parameterCount: number;
    readonly name: string;
    readonly bodyStart: number;
    readonly bodyEnd: number;
  };
  TSDeclareFunction: {
    readonly nodeKind: 'TSDeclareFunction';
    readonly async: boolean;
    readonly generator: boolean;
    readonly parameterCount: number;
    readonly name: string;
    readonly bodyStart: number;
    readonly bodyEnd: number;
  };
  ClassDeclaration: {
    readonly nodeKind: 'ClassDeclaration';
    readonly name: string;
  };
  ClassExpression: {
    readonly nodeKind: 'ClassExpression';
    readonly name: string;
  };
}

